  async function daily(){if(!perms().daily){tab='dashboard';dashboard();return}const v100MailAdmin=String(state?.profile?.rol||'').trim().toUpperCase()==='ADMIN_TOTAL';setHead('Reporte diario',v100MailAdmin?'Revisados emitidos hoy y pendientes separados por galera, listos para compartir por correo.':'Revisados emitidos hoy y pendientes separados por galera.');const em=data?.emitidos_hoy?.rows||[],groups=dailyPendingGroups(),pend=groups.reduce((a,g)=>a+g.rows.length,0),topGal=[...groups].sort((a,b)=>b.rows.length-a.rows.length)[0];$('#v66Body').innerHTML=`<div class="v66-daily-summary"><article class="good"><span>Emitidos hoy</span><strong>${num(em.length)}</strong><small>Revisados registrados durante el día.</small></article><article class="danger"><span>Pendientes</span><strong>${num(pend)}</strong><small>Separados por galera para seguimiento.</small></article><article><span>Galera con más pendientes</span><strong>${E(topGal?.galera||'—')}</strong><small>${topGal?`${num(topGal.rows.length)} pendientes`:'Sin pendientes'}</small></article></div><div class="v66-daily-layout"><div><section class="v66-card"><div class="v66-card-head"><div><h3>Revisados emitidos hoy</h3><p>Unidades que ya registran emisión durante el día actual.</p></div><span class="v66-sync-label">${num(em.length)} emitidos</span></div>${dailyTable(em,'emitted')}</section><section class="v66-card" style="margin-top:13px"><div class="v66-card-head"><div><h3>Pendientes por galera</h3><p>Cada bloque muestra únicamente las unidades que todavía requieren revisado.</p></div><span class="v66-sync-label">${num(pend)} pendientes</span></div>${groups.map(g=>`<section class="v66-daily-group"><div class="v66-daily-group-title"><b>${E(g.galera)}</b><span>${num(g.rows.length)} pendientes</span></div>${dailyTable(g.rows)}</section>`).join('')||'<div class="v66-empty">✓ No hay pendientes dentro de tu alcance.</div>'}</section></div><aside class="v66-card v66-daily-sendbox ${v100MailAdmin?'':'v100-mail-hidden'}"><div class="v66-card-head"><div><h3>Enviar por correo</h3><p>Selecciona uno o varios destinatarios antes de enviar.</p></div></div><div class="v66-daily-from"><span>Remitente</span><b>panapassrym@gmail.com</b></div><input id="v66DailyRecipientQ" class="v66-daily-search" placeholder="Buscar nombre, correo, rol o galera"><div class="v66-daily-rec-actions"><button id="v66DailyAll">Seleccionar visibles</button><button id="v66DailyNone">Limpiar</button></div><div id="v66DailyRecipients" class="v66-recipient-list"><div class="v66-empty">Cargando correos...</div></div><div class="v66-manual-mail"><input id="v66DailyManual" type="email" placeholder="Agregar correo manual"><button id="v66DailyManualBtn">Agregar</button></div><div id="v66DailySelected" class="v66-daily-selected"><b>0</b> destinatarios seleccionados</div><div class="v66-daily-send-actions"><button id="v66DailyPreview" class="soft">Vista previa</button><button id="v66DailySend">Enviar reporte</button></div></aside></div>`;if(!v100MailAdmin)return;bindDailyRecipients();try{const list=await loadDailyRecipients();const box=$('#v66DailyRecipients');if(box){box.innerHTML=recipientCards(list);bindDailyRecipients();updateDailySelected()}}catch(e){const box=$('#v66DailyRecipients');if(box)box.innerHTML=`<div class="v66-empty">${E(e.message||e)}</div>`}}
  function render(){if(!data)return;const p=perms();if(tab==='operations'&&!p.operations)tab='dashboard';if(tab==='monthly'&&!p.monthly)tab='dashboard';if(tab==='daily'&&!p.daily)tab='dashboard';if(tab==='history'&&!p.history)tab='dashboard';if(tab==='stats'&&!p.stats)tab='dashboard';if(tab==='boletas'&&!p.boletas)tab='dashboard';if(tab==='cupos'&&!p.cupos)tab='dashboard';if(tab==='dashboard')dashboard();else if(tab==='operations')operations();else if(tab==='monthly')monthly();else if(tab==='daily')daily();else if(tab==='history')history();else if(tab==='stats')stats();else if(tab==='boletas')boletas();else if(tab==='cupos')cupos();else dashboard()}
  window.v60OpenRevisados=async function(){const app=appEl();if(!app)return;tab='dashboard';preset={};document.body.classList.remove('v60-revisados');document.body.classList.add('v66-revisados');const userKey=String((typeof state!=='undefined'&&state?.profile?.id)||'')+'|'+N((typeof state!=='undefined'&&state?.profile?.rol)||'');if(data&&cacheUserKey===userKey&&(Date.now()-dataLoadedAt)<120000){shell();render();return}if(cacheUserKey!==userKey){data=null;incidents=[];incidentTypes=[];cacheUserKey=userKey;dataLoadedAt=0}app.innerHTML='<div style="padding:30px;font-family:Inter,system-ui">Cargando Revisados...</div>';try{await load(false);shell();render()}catch(e){document.body.classList.remove('v66-revisados');app.innerHTML=`<div class="wrap"><div class="alert">Revisados: ${E(e.message||e)}</div><button onclick="window.v36PortalHome&&window.v36PortalHome()">Volver</button></div>`}}
